Here's the result of running `cat -n` on /workspace/MERGEEVENTINGESTION/ENDTOEND/services/sources/malmolive.js:
     1	// Malmö Live - Event Source
     2	// API: https://malmolive.se/api/events
     3	
     4	const MALMO_LIVE_API = 'https://malmolive.se/api/events';
     5	
     6	function mapMalmöLiveEvent(item) {
     7	  const title = item.title || 'Untitled Event';
     8	  
     9	  // Parse date and time
    10	  let date = '';
    11	  let time = '';
    12	  if (item.field_date_time) {
    13	    const dt = new Date(item.field_date_time);
    14	    date = dt.toISOString().split('T')[0];
    15	    time = dt.toTimeString().substring(0, 5);
    16	  }
    17	  
    18	  const venue = item.field_venue || 'Malmö Live';
    19	  const area = 'Malmö';
    20	  
    21	  let category = 'culture';
    22	  const keywords = item.field_keywords_target_id || '';
    23	  if (keywords.includes('Jazz') || keywords.includes('Pop') || keywords.includes('Rock')) {
    24	    category = 'music';
    25	  } else if (keywords.includes('Opera') || keywords.includes('Symfoni')) {
    26	    category = 'music';
    27	  } else if (keywords.includes('Barn') || keywords.includes('familj')) {
    28	    category = 'family';
    29	  }
    30	  
    31	  let url = '';
    32	  if (item.view_node) {
    33	    url = 'https://malmolive.se' + item.view_node;
    34	  }
    35	  
    36	  return {
    37	    id: `malmo-live-${item.tessitura_event_id || item.tessitura_instance_id || Math.random()}`,
    38	    title,
    39	    date,
    40	    time,
    41	    venue,
    42	    area,
    43	    address: '',
    44	    description: item.field_text_plain_long || '',
    45	    url,
    46	    category,
    47	    source: 'malmo-live',
    48	  };
    49	}
    50	
    51	export async function fetchMalmöLiveEvents(options = {}) {
    52	  const { limit = 100 } = options;
    53	  
    54	  try {
    55	    const response = await fetch(MALMO_LIVE_API, {
    56	      headers: {
    57	        'User-Agent': 'EventPulse/1.0',
    58	        'Accept': 'application/json',
    59	      },
    60	    });
    61	    
    62	    if (!response.ok) {
    63	      console.warn('Malmö Live fetch failed:', response.status);
    64	      return [];
    65	    }
    66	    
    67	    const data = await response.json();
    68	    
    69	    if (!Array.isArray(data)) {
    70	      console.warn('Malmö Live: Unexpected data format');
    71	      return [];
    72	    }
    73	    
    74	    // Map events
    75	    let events = data.map(mapMalmöLiveEvent);
    76	    
    77	    // Filter: only future events within 1 year
    78	    const now = new Date();
    79	    const oneYear = new Date();
    80	    oneYear.setFullYear(oneYear.getFullYear() + 1);
    81	    
    82	    events = events.filter(e => {
    83	      if (!e.date) return false;
    84	      const eventDate = new Date(e.date);
    85	      return eventDate >= now && eventDate <= oneYear;
    86	    });
    87	    
    88	    return events.slice(0, limit);
    89	  } catch (error) {
    90	    console.error('Error fetching Malmö Live events:', error);
    91	    return [];
    92	  }
    93	}
